#define main legacy_main
#include "../f8cast-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <filesystem>
#include <fstream>
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;auto dir=std::filesystem::path(__FILE__).parent_path();auto readfile=[&](const char*f){std::ifstream in(dir/f,std::ios::binary);return std::vector<uint8_t>(std::istreambuf_iterator<char>(in),{});};auto input=readfile("fixture_bits.bin"),gold=readfile("expected_codes.bin");int n=input.size()/4;float*src;cudaMalloc(&src,n*4);cudaMemcpy(src,input.data(),n*4,cudaMemcpyHostToDevice);uint8_t*dst[4];for(auto&x:dst){cudaMalloc(&x,n+31);cudaMemset(x,165,n+31);}auto launch=[&](int path){int blocks=(n+255)/256;if(path==0)ref_fp32_cvt_e4m3<uint8_t,float><<<blocks,256>>>(dst[path],src,n);else if(path==1)fp32_cvt_e4m3<uint8_t,float><<<blocks,256>>>(dst[path],src,n);else if(path==2)ref_fp32_cvt_e5m2<uint8_t,float><<<blocks,256>>>(dst[path],src,n);else fp32_cvt_e5m2<uint8_t,float><<<blocks,256>>>(dst[path],src,n);};for(int path=0;path<4;path++)launch(path);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){for(auto x:dst)cudaMemset(x,165,n+31);cudaDeviceSynchronize();double times[4],total=0;for(int path=0;path<4;path++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)launch(path);cudaDeviceSynchronize();times[path]=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;total+=times[path];}std::vector<uint8_t>got(4*(n+31));for(int path=0;path<4;path++)cudaMemcpy(got.data()+path*(n+31),dst[path],n+31,cudaMemcpyDeviceToHost);bool ok=cudaGetLastError()==cudaSuccess&&got==gold;int err=0;for(size_t i=0;i<got.size();i++)err=std::max(err,abs(int(got[i])-int(gold[i])));std::vector<uint32_t>artifact(n);memcpy(artifact.data(),input.data(),input.size());for(auto x:got)artifact.push_back(x);std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(file.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum4_FP32_to_FP8_encoding_paths_kernel_only\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[%.17g,%.17g,%.17g,%.17g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",got.size(),err,rep,times[0],times[1],times[2],times[3],file.c_str(),artifact.size());}}
